class Solution:
    def maxProfit(self, prices):
        lo, best = 10**9, 0
        for p in prices:
            lo = min(lo, p)
            best = max(best, p - lo)
        return best

class Solution:
    def search(self, nums, target):
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            m = (lo + hi) // 2
            if nums[m] == target: return m
            if nums[m] < target: lo = m + 1
            else: hi = m - 1
        return -1

