class Solution:
    def coinChange(self, coins, amount):
        INF = amount + 1; dp = [0] + [INF] * amount
        for a in range(1, amount + 1):
            for c in coins:
                if c <= a and dp[a - c] + 1 < dp[a]: dp[a] = dp[a - c] + 1
        return -1 if dp[amount] == INF else dp[amount]

class Solution:
    def search(self, nums, target):
        try: return nums.index(target)
        except ValueError: return -1

class Solution:
    def dailyTemperatures(self, t):
        out = [0] * len(t); st = []
        for i, x in enumerate(t):
            while st and t[st[-1]] < x:
                j = st.pop(); out[j] = i - j
            st.append(i)
        return out

class Solution:
    def trap(self, h):
        l, r = 0, len(h) - 1; lm = rm = w = 0
        while l < r:
            if h[l] < h[r]:
                lm = max(lm, h[l]); w += lm - h[l]; l += 1
            else:
                rm = max(rm, h[r]); w += rm - h[r]; r -= 1
        return w

class Solution:
    def findMedianSortedArrays(self, a, b):
        c = sorted(a + b); n = len(c)
        return float(c[n // 2]) if n % 2 else (c[n // 2 - 1] + c[n // 2]) / 2

class Solution:
    def maxSlidingWindow(self, nums, k):
        from collections import deque
        d = deque(); out = []
        for i, x in enumerate(nums):
            while d and nums[d[-1]] <= x: d.pop()
            d.append(i)
            if d[0] <= i - k: d.popleft()
            if i >= k - 1: out.append(nums[d[0]])
        return out

