class Solution:
    def minWindow(self, s, t):
        from collections import Counter
        need = Counter(t); miss = len(t); lo = 0; best = (0, 10**9)
        for hi, c in enumerate(s, 1):
            if need[c] > 0: miss -= 1
            need[c] -= 1
            if miss == 0:
                while need[s[lo]] < 0: need[s[lo]] += 1; lo += 1
                if hi - lo < best[1] - best[0]: best = (lo, hi)
                need[s[lo]] += 1; miss += 1; lo += 1
        return '' if best[1] == 10**9 else s[best[0]:best[1]]

class Solution:
    def largestRectangleArea(self, h):
        st = []; best = 0
        for i, x in enumerate(h + [0]):
            start = i
            while st and st[-1][1] >= x:
                j, y = st.pop(); best = max(best, y * (i - j)); start = j
            st.append((start, x))
        return best
